+            {createMutation.isPending ? "Creating…" : "Create mission"}
+          </button>
+          <button
+            type="button"
+            onClick={onCancel}
+            className="rounded-md border border-border px-4 py-2.5 text-sm font-semibold text-text-2"
+          >
+            Cancel
+          </button>
+        </div>
+      </form>
+    </div>
+  );
+}
